#!/bin/bash
# Docker build script for Video Chapter Automater
# Supports multiple build types, architectures, and optimization levels

set -euo pipefail

# Configuration
IMAGE_NAME="video-chapter-automater"
REGISTRY="${REGISTRY:-}"  # Set to your registry URL
VERSION="${VERSION:-latest}"
PYTHON_VERSION="${PYTHON_VERSION:-3.11}"
UV_VERSION="${UV_VERSION:-0.4.15}"
BUILD_TYPE="${BUILD_TYPE:-production}"
PLATFORM="${PLATFORM:-linux/amd64}"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Logging functions
log_info() { echo -e "${BLUE}[INFO]${NC} $1"; }\nlog_warn() { echo -e "${YELLOW}[WARN]${NC} $1"; }\nlog_error() { echo -e "${RED}[ERROR]${NC} $1"; }\nlog_success() { echo -e "${GREEN}[SUCCESS]${NC} $1"; }\n\n# Help function\nshow_help() {\n    cat << EOF\nUsage: $0 [OPTIONS]\n\nBuild Docker images for Video Chapter Automater with uv package management.\n\nOPTIONS:\n    -t, --type TYPE         Build type: production, development, gpu-test (default: production)\n    -p, --platform PLATFORM Target platform: linux/amd64, linux/arm64, or linux/amd64,linux/arm64 (default: linux/amd64)\n    -v, --version VERSION   Image version tag (default: latest)\n    -r, --registry REGISTRY Container registry URL (default: none)\n    --python VERSION        Python version (default: 3.11)\n    --uv VERSION           UV version (default: 0.4.15)\n    --push                 Push images to registry after build\n    --no-cache             Disable Docker build cache\n    --dry-run              Show commands without executing\n    --multi-arch           Build for multiple architectures\n    -h, --help             Show this help message\n\nEXAMPLES:\n    # Basic production build\n    $0\n\n    # Development build with multi-architecture support\n    $0 --type development --multi-arch\n\n    # Production build and push to registry\n    $0 --type production --version v1.2.3 --registry myregistry.com --push\n\n    # CPU-only build (no GPU dependencies)\n    FORCE_CPU=true $0 --type production\n\n    # Build with custom Python version\n    $0 --python 3.12 --version py312\nEOF\n}\n\n# Parse command line arguments\nPUSH=false\nNO_CACHE=false\nDRY_RUN=false\nMULTI_ARCH=false\n\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        -t|--type)\n            BUILD_TYPE=\"$2\"\n            shift 2\n            ;;\n        -p|--platform)\n            PLATFORM=\"$2\"\n            shift 2\n            ;;\n        -v|--version)\n            VERSION=\"$2\"\n            shift 2\n            ;;\n        -r|--registry)\n            REGISTRY=\"$2\"\n            shift 2\n            ;;\n        --python)\n            PYTHON_VERSION=\"$2\"\n            shift 2\n            ;;\n        --uv)\n            UV_VERSION=\"$2\"\n            shift 2\n            ;;\n        --push)\n            PUSH=true\n            shift\n            ;;\n        --no-cache)\n            NO_CACHE=true\n            shift\n            ;;\n        --dry-run)\n            DRY_RUN=true\n            shift\n            ;;\n        --multi-arch)\n            MULTI_ARCH=true\n            PLATFORM=\"linux/amd64,linux/arm64\"\n            shift\n            ;;\n        -h|--help)\n            show_help\n            exit 0\n            ;;\n        *)\n            log_error \"Unknown option: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\ndone\n\n# Validate build type\ncase $BUILD_TYPE in\n    production|development|gpu-test)\n        ;;\n    *)\n        log_error \"Invalid build type: $BUILD_TYPE\"\n        log_info \"Valid types: production, development, gpu-test\"\n        exit 1\n        ;;\nesac\n\n# Construct image tag\nif [[ -n \"$REGISTRY\" ]]; then\n    FULL_IMAGE_NAME=\"${REGISTRY}/${IMAGE_NAME}\"\nelse\n    FULL_IMAGE_NAME=\"$IMAGE_NAME\"\nfi\n\nIMAGE_TAG=\"${FULL_IMAGE_NAME}:${VERSION}\"\nBUILD_TAG=\"${FULL_IMAGE_NAME}:${BUILD_TYPE}-${VERSION}\"\nCACHE_TAG=\"${FULL_IMAGE_NAME}:cache\"\n\n# Build command construction\nBUILD_CMD=\"docker buildx build\"\n\n# Add platform support\nif [[ \"$MULTI_ARCH\" == true ]]; then\n    BUILD_CMD=\"$BUILD_CMD --platform $PLATFORM\"\n    log_info \"Building for multiple architectures: $PLATFORM\"\nelse\n    BUILD_CMD=\"$BUILD_CMD --platform $PLATFORM\"\nfi\n\n# Add cache options\nif [[ \"$NO_CACHE\" == true ]]; then\n    BUILD_CMD=\"$BUILD_CMD --no-cache\"\nelse\n    BUILD_CMD=\"$BUILD_CMD --cache-from $CACHE_TAG\"\nfi\n\n# Add build arguments\nBUILD_CMD=\"$BUILD_CMD --build-arg PYTHON_VERSION=$PYTHON_VERSION\"\nBUILD_CMD=\"$BUILD_CMD --build-arg UV_VERSION=$UV_VERSION\"\nBUILD_CMD=\"$BUILD_CMD --build-arg BUILD_TYPE=$BUILD_TYPE\"\nBUILD_CMD=\"$BUILD_CMD --build-arg BUILDKIT_INLINE_CACHE=1\"\n\n# Target stage\nBUILD_CMD=\"$BUILD_CMD --target $BUILD_TYPE\"\n\n# Tags\nBUILD_CMD=\"$BUILD_CMD --tag $IMAGE_TAG\"\nBUILD_CMD=\"$BUILD_CMD --tag $BUILD_TAG\"\nBUILD_CMD=\"$BUILD_CMD --tag $CACHE_TAG\"\n\n# Add push if requested and not dry run\nif [[ \"$PUSH\" == true && \"$DRY_RUN\" == false ]]; then\n    BUILD_CMD=\"$BUILD_CMD --push\"\nfi\n\n# Add context\nBUILD_CMD=\"$BUILD_CMD .\"\n\n# Display build information\nlog_info \"Docker Build Configuration:\"\necho \"  Image: $IMAGE_TAG\"\necho \"  Build Type: $BUILD_TYPE\"\necho \"  Platform: $PLATFORM\"\necho \"  Python: $PYTHON_VERSION\"\necho \"  UV: $UV_VERSION\"\necho \"  Multi-arch: $MULTI_ARCH\"\necho \"  Push: $PUSH\"\necho \"  No Cache: $NO_CACHE\"\n\n# Check for required tools\nif ! command -v docker &> /dev/null; then\n    log_error \"Docker is not installed or not in PATH\"\n    exit 1\nfi\n\nif [[ \"$MULTI_ARCH\" == true ]] && ! docker buildx version &> /dev/null; then\n    log_error \"Docker Buildx is required for multi-architecture builds\"\n    exit 1\nfi\n\n# Create buildx builder if multi-arch\nif [[ \"$MULTI_ARCH\" == true ]]; then\n    BUILDER_NAME=\"video-chapter-builder\"\n    if ! docker buildx inspect \"$BUILDER_NAME\" &> /dev/null; then\n        log_info \"Creating multi-architecture builder: $BUILDER_NAME\"\n        if [[ \"$DRY_RUN\" == false ]]; then\n            docker buildx create --name \"$BUILDER_NAME\" --use\n            docker buildx inspect --bootstrap\n        fi\n    else\n        docker buildx use \"$BUILDER_NAME\"\n    fi\nfi\n\n# Execute build\nlog_info \"Executing build command:\"\necho \"$BUILD_CMD\"\n\nif [[ \"$DRY_RUN\" == true ]]; then\n    log_warn \"Dry run mode - not executing build\"\n    exit 0\nfi\n\nlog_info \"Starting Docker build...\"\nif eval \"$BUILD_CMD\"; then\n    log_success \"Docker build completed successfully!\"\n    \n    # Display image information\n    if [[ \"$PUSH\" == false ]]; then\n        log_info \"Built images:\"\n        docker images --filter \"reference=$FULL_IMAGE_NAME\" --format \"table {{.Repository}}:{{.Tag}}\\t{{.Size}}\\t{{.CreatedSince}}\"\n    fi\n    \n    # GPU test if requested\n    if [[ \"$BUILD_TYPE\" == \"gpu-test\" ]]; then\n        log_info \"Running GPU capability test...\"\n        docker run --rm --gpus all \"$IMAGE_TAG\" || {\n            log_warn \"GPU test failed - this is normal if no GPU is available\"\n        }\n    fi\n    \nelse\n    log_error \"Docker build failed!\"\n    exit 1\nfi\n\nlog_success \"All operations completed successfully!\"\n\n# Cleanup builder if created\nif [[ \"$MULTI_ARCH\" == true && -n \"$BUILDER_NAME\" ]]; then\n    log_info \"Cleaning up builder: $BUILDER_NAME\"\n    # docker buildx rm \"$BUILDER_NAME\" || true\nfi